import type { MetadataRoute } from "next";

/**
 * Installable web app manifest. Icons are generated by
 * `scripts/generate-icons.mjs`; `icon-maskable-512.png` keeps the star inside
 * Android's safe zone.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "StarsTask",
    short_name: "StarsTask",
    description:
      "Browse university assignments by course, semester, deadline, and tag. Sign in with Google to contribute your own.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#fafaf8",
    theme_color: "#17352b",
    lang: "en",
    categories: ["education", "productivity"],
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
